package com.library.catalogsets;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.jdbc.core.JdbcTemplate;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static com.library.catalogattributes.CatalogAttributeSupport.JSON;
import static com.library.catalogattributes.CatalogAttributeSupport.obj;
import static com.library.catalogattributes.CatalogAttributeSupport.hash;
import static com.library.catalogattributes.CatalogAttributeSupport.read;
import static com.library.catalogattributes.CatalogAttributeSupport.bytes;
import static com.library.catalogattributes.CatalogAttributeSupport.num;
import static com.library.catalogattributes.CatalogAttributeSupport.nullable;
import static com.library.catalogattributes.CatalogAttributeSupport.now;
import static com.library.catalogattributes.CatalogAttributeSupport.placeholders;
import static com.library.catalogsets.CatalogSetSupport.*;

/** SQL filters aggregated cases before LIMIT. Only the one fixed JSON path is projected. */
final class CatalogSetSourceQuery {
    final JdbcTemplate jdbc;final boolean mysql;
    CatalogSetSourceQuery(JdbcTemplate j){jdbc=j;try(var c=Objects.requireNonNull(j.getDataSource()).getConnection()){mysql=c.getMetaData().getDatabaseProductName().equals("MySQL");}catch(Exception e){throw failure(500,"CATALOG_SET_SAVE_FAILED");}}
    String bin(String s){return "CAST("+s+" AS "+(mysql?"BINARY":"VARBINARY")+")";}
    String exact(String a,String b){return bin(a)+"="+bin(b);}
    String sha(String s){return mysql?"SHA2("+s+",256)":"B34_JSON_VALUE_HASH("+s+")";}
    String whitespacePattern(){StringBuilder s=new StringBuilder("^[");for(int cp=1;cp<=0x3000;cp++)if(Character.isWhitespace(cp)||Character.isSpaceChar(cp))s.appendCodePoint(cp);return s.append("]+$").toString();}
    String rawSql(){String doc="CASE WHEN JSON_VALID(l.details_json) THEN l.details_json ELSE '{}' END",path="'$.\"套装类型\"'";return "SELECT l.id,l.source_system,l.record_type,l.source_key,l.book_id,sb.deleted AS source_deleted,CASE WHEN JSON_VALID(l.details_json) THEN JSON_TYPE("+doc+") ELSE 'INVALID' END AS root_kind,JSON_CONTAINS_PATH("+doc+",'one',"+path+") AS present,JSON_EXTRACT("+doc+","+path+") AS cell_json,JSON_TYPE(JSON_EXTRACT("+doc+","+path+")) AS value_kind,JSON_UNQUOTE(JSON_EXTRACT("+doc+","+path+")) AS raw_value FROM legacy_record l LEFT JOIN book sb ON sb.id=l.book_id WHERE "+exact("l.source_system","'huiben'")+" AND "+exact("l.record_type","'BOOK'");}
    String cte(){String raw=rawSql();String marker="CASE WHEN r.root_kind<>'OBJECT' THEN 'WRONG_TYPE' WHEN r.present=0 THEN 'MISSING' WHEN r.value_kind='NULL' THEN 'NULL' WHEN r.value_kind<>'STRING' THEN 'WRONG_TYPE' WHEN CHAR_LENGTH(r.raw_value)=0 THEN 'EMPTY' WHEN REGEXP_LIKE(r.raw_value,'"+whitespacePattern()+"') THEN 'WHITESPACE' WHEN "+exact("r.raw_value","'暂无设置'")+" THEN 'UNSET' WHEN "+exact("r.raw_value","'套装中单本'")+" THEN 'MEMBER_MARKER' ELSE 'UNMAPPED' END";
        // DISTINCT is neutral because source id is unique, and prevents the
        // raw JSON projection from being merged and reparsed at every link.
        // This materialization lives only within the current SQL statement.
        // Aggregate actual source links first. Joining every subject to the
        // mixed book/orphan links with OR prevents an indexed equality join.
        // The final equality join restores zero-source books; orphan IDs keep
        // each unassociated source separate, including when book IDs collide.
        return "WITH raw_source AS (SELECT DISTINCT projected.* FROM ("+raw+") projected), matches AS (SELECT c.barcode_key,COUNT(*) AS match_count,MIN(c.book_id) AS copy_book,SUM(CASE WHEN b.id IS NULL OR b.deleted<>0 THEN 1 ELSE 0 END) AS invalid_count FROM book_copy c LEFT JOIN book b ON b.id=c.book_id GROUP BY c.barcode_key), classified AS (SELECT r.*,"+marker+" AS marker,CONCAT(r.root_kind,':',r.present,':',CASE WHEN r.present=0 THEN 'MISSING' WHEN r.value_kind='NULL' THEN 'NULL' WHEN r.value_kind='STRING' THEN 'STRING' ELSE 'NON_STRING' END,':',COALESCE("+sha("r.cell_json")+",'missing')) AS fingerprint,CASE WHEN m.match_count=1 AND m.copy_book=r.book_id AND r.source_deleted=0 AND m.invalid_count=0 THEN 0 ELSE 1 END AS invalid_association FROM raw_source r LEFT JOIN matches m ON m.barcode_key="+bin("r.source_key")+"), linked_books AS (SELECT b.id AS case_book,r.id AS case_record FROM raw_source r JOIN book b ON b.id=r.book_id UNION SELECT b.id AS case_book,r.id AS case_record FROM raw_source r JOIN book_copy c ON c.barcode_key="+bin("r.source_key")+" JOIN book b ON b.id=c.book_id), links AS (SELECT case_book,CAST(NULL AS "+(mysql?"SIGNED":"BIGINT")+") AS orphan_id,case_record FROM linked_books UNION ALL SELECT NULL AS case_book,r.id AS orphan_id,r.id AS case_record FROM raw_source r WHERE NOT EXISTS(SELECT 1 FROM book b WHERE b.id=r.book_id) AND NOT EXISTS(SELECT 1 FROM book_copy c JOIN book b ON b.id=c.book_id WHERE c.barcode_key="+bin("r.source_key")+")), source_aggregates AS (SELECT l.case_book,l.orphan_id,COUNT(r.id) AS source_count,COUNT(DISTINCT r.fingerprint) AS variants,MIN(r.marker) AS single_marker,COALESCE(MAX(r.invalid_association),0) AS invalid_association,COALESCE(MAX(CASE WHEN r.marker='MEMBER_MARKER' THEN 1 ELSE 0 END),0) AS has_marker,COALESCE(MAX(CASE WHEN r.marker='UNMAPPED' THEN 1 ELSE 0 END),0) AS has_unmapped,COALESCE(MAX(CASE WHEN r.marker IN ('MISSING','NULL','EMPTY','WHITESPACE','UNSET','WRONG_TYPE') THEN 1 ELSE 0 END),0) AS has_incomplete FROM links l JOIN classified r ON r.id=l.case_record GROUP BY l.case_book,l.orphan_id), aggregated AS (SELECT b.id AS case_book,CAST(NULL AS "+(mysql?"SIGNED":"BIGINT")+") AS orphan_id,COALESCE(g.source_count,0) AS source_count,COALESCE(g.variants,0) AS variants,g.single_marker,COALESCE(g.invalid_association,0) AS invalid_association,COALESCE(g.has_marker,0) AS has_marker,COALESCE(g.has_unmapped,0) AS has_unmapped,COALESCE(g.has_incomplete,0) AS has_incomplete FROM book b LEFT JOIN source_aggregates g ON g.case_book=b.id UNION ALL SELECT case_book,orphan_id,source_count,variants,single_marker,invalid_association,has_marker,has_unmapped,has_incomplete FROM source_aggregates WHERE case_book IS NULL), relationships AS (SELECT m.book_id,COUNT(*) AS history_count,SUM(CASE WHEN m.status='ACTIVE' AND s.status='ACTIVE' THEN 1 ELSE 0 END) AS active_count FROM catalog_set_member m JOIN catalog_set s ON s.id=m.set_id GROUP BY m.book_id), cases AS (SELECT g.*,"+CatalogSetService.BOOK_COLUMNS+",CASE WHEN g.source_count=0 THEN 'NO_SOURCE' WHEN g.variants>1 THEN 'CONFLICT' ELSE g.single_marker END AS marker_state,CASE WHEN g.source_count=0 THEN 'NO_SOURCE' WHEN g.invalid_association>0 THEN 'ASSOCIATION_INVALID' ELSE 'VALID' END AS association_state,COALESCE(rel.history_count,0) AS history_count,COALESCE(rel.active_count,0) AS active_count,CASE WHEN rel.active_count>0 THEN 'ACTIVE' WHEN rel.history_count>0 THEN 'HISTORICAL' ELSE 'NONE' END AS relationship_state FROM aggregated g LEFT JOIN book b ON b.id=g.case_book LEFT JOIN catalog_book_attribute a ON a.book_id=b.id LEFT JOIN relationships rel ON rel.book_id=g.case_book) ";
    }
    static long caseId(String key){if(key==null||!key.matches("SET_SOURCE_(BOOK|RECORD):[1-9][0-9]*"))invalid();return queryNumber(key.substring(key.indexOf(':')+1),true);}
    static boolean bookCase(String k){return k.startsWith("SET_SOURCE_BOOK:");}
    static String rowKey(Map<String,Object> row){return row.get("case_book")==null?"SET_SOURCE_RECORD:"+num(row.get("orphan_id")):"SET_SOURCE_BOOK:"+num(row.get("case_book"));}
    static final class CaseData {
        final String key;final ArrayNode records=JSON.createArrayNode(),fingerprints=JSON.createArrayNode();final Set<String> states=new HashSet<>(),variants=new HashSet<>();boolean invalid;
        CaseData(String key){this.key=key;}
        String marker(){return records.isEmpty()?"NO_SOURCE":variants.size()>1?"CONFLICT":states.iterator().next();}
        String association(){return records.isEmpty()?"NO_SOURCE":invalid?"ASSOCIATION_INVALID":"VALID";}
        String digest(){return hash(obj("schemaVersion",1,"parserVersion","huiben-book-set-v1","caseKey",key,"records",fingerprints));}
        ObjectNode summary(){ArrayNode reasons=JSON.createArrayNode();for(String reason:REASONS){boolean yes=switch(reason){case "MEMBER_MARKER_NO_PARENT"->states.contains("MEMBER_MARKER");case "SOURCE_CONFLICT"->variants.size()>1;case "ASSOCIATION_INVALID"->invalid;case "UNMAPPED_MARKER"->states.contains("UNMAPPED");case "NO_SOURCE"->records.isEmpty();case "INCOMPLETE_SOURCE_VALUE"->states.stream().anyMatch(s->List.of("MISSING","NULL","EMPTY","WHITESPACE","UNSET","WRONG_TYPE").contains(s));default->records.size()>200;};if(yes)reasons.add(reason);}return obj("parserVersion","huiben-book-set-v1","sourceCount",records.size(),"associationState",association(),"markerState",marker(),"reasons",reasons,"digest",digest(),"readAt",now());}
    }
    Map<String,CaseData> load(List<String> keys){Map<String,CaseData> result=new LinkedHashMap<>();keys.forEach(k->result.put(k,new CaseData(k)));if(keys.isEmpty())return result;List<Object> args=new ArrayList<>();List<String> clauses=new ArrayList<>();List<Long> books=keys.stream().filter(CatalogSetSourceQuery::bookCase).map(CatalogSetSourceQuery::caseId).toList(),orphans=keys.stream().filter(k->!bookCase(k)).map(CatalogSetSourceQuery::caseId).toList();if(!books.isEmpty()){clauses.add("(r.book_id IN ("+placeholders(books.size())+") OR EXISTS(SELECT 1 FROM book_copy c WHERE c.book_id IN ("+placeholders(books.size())+") AND c.barcode_key="+bin("r.source_key")+"))");args.addAll(books);args.addAll(books);}if(!orphans.isEmpty()){clauses.add("r.id IN ("+placeholders(orphans.size())+")");args.addAll(orphans);}var rows=jdbc.queryForList("SELECT r.* FROM ("+rawSql()+") r WHERE "+String.join(" OR ",clauses)+" ORDER BY r.id",args.toArray());List<Map<String,Object>> copies=copies(rows);Map<String,List<Map<String,Object>>> byKey=new HashMap<>();for(var c:copies)byKey.computeIfAbsent(HexFormat.of().formatHex((byte[])c.get("barcode_key")),k->new ArrayList<>()).add(c);for(var r:rows){List<Map<String,Object>> matches=byKey.getOrDefault(HexFormat.of().formatHex(bytes(str(r.get("source_key")))),List.of());Set<Long> associated=new HashSet<>();if(r.get("source_deleted")!=null)associated.add(nullable(r.get("book_id")));for(var c:matches)if(c.get("deleted")!=null)associated.add(num(c.get("book_id")));for(String key:keys)if(bookCase(key)?associated.contains(caseId(key)):caseId(key)==num(r.get("id"))&&associated.isEmpty())append(result.get(key),r,matches);}return result;}
    String str(Object v){if(v instanceof byte[] b)return new String(b,StandardCharsets.UTF_8);return CatalogSetService.str(v);}
    List<Map<String,Object>> copies(List<Map<String,Object>> rows){if(rows.isEmpty())return List.of();List<Object> args=rows.stream().map(r->(Object)bytes(str(r.get("source_key")))).distinct().toList();return jdbc.queryForList("SELECT c.id,c.book_id,c.barcode_key,b.deleted FROM book_copy c LEFT JOIN book b ON b.id=c.book_id WHERE c.barcode_key IN ("+placeholders(args.size())+") ORDER BY c.id",args.toArray());}
    static String marker(String root,boolean present,JsonNode value){if(!root.equals("OBJECT"))return "WRONG_TYPE";if(!present)return "MISSING";if(value.isNull())return "NULL";if(!value.isTextual())return "WRONG_TYPE";String s=value.textValue();if(s.isEmpty())return "EMPTY";if(whitespace(s))return "WHITESPACE";if(s.equals("暂无设置"))return "UNSET";if(s.equals("套装中单本"))return "MEMBER_MARKER";return "UNMAPPED";}
    void append(CaseData target,Map<String,Object> row,List<Map<String,Object>> matches){boolean present=Boolean.TRUE.equals(row.get("present"))||row.get("present") instanceof Number n&&n.intValue()==1;String root=str(row.get("root_kind"));JsonNode value=row.get("cell_json")==null?NullNode.instance:read(str(row.get("cell_json")));String valueHash=hash(obj("present",present,"value",value)),state=marker(root,present,value);boolean valid=matches.size()==1&&Objects.equals(nullable(row.get("book_id")),nullable(matches.get(0).get("book_id")))&&row.get("source_deleted")!=null&&num(row.get("source_deleted"))==0&&matches.get(0).get("deleted")!=null&&num(matches.get(0).get("deleted"))==0;target.invalid|=!valid;target.states.add(state);target.variants.add(root+":"+present+":"+(!present?"MISSING":value.isNull()?"NULL":value.isTextual()?"STRING":"NON_STRING")+":"+valueHash);ArrayNode copyMatches=JSON.createArrayNode();for(var c:matches)copyMatches.add(obj("copyId",c.get("id"),"bookId",c.get("book_id"),"deleted",deleted(c.get("deleted"))));String raw=value.isTextual()&&value.textValue().codePointCount(0,value.textValue().length())<=2000?value.textValue():null;String cellKind=!present?"MISSING":value.isNull()?"NULL":value.isTextual()?"STRING":"NON_STRING";target.records.add(obj("recordId",row.get("id"),"sourceKey",str(row.get("source_key")),"sourceBookId",row.get("book_id"),"sourceBookDeleted",deleted(row.get("source_deleted")),"copyMatches",copyMatches,"rootKind",root,"cell",obj("kind",cellKind,"rawValue",raw,"valueSha256",valueHash),"associationState",valid?"VALID":"ASSOCIATION_INVALID"));target.fingerprints.add(obj("recordId",row.get("id"),"sourceSystemHex",hex(str(row.get("source_system"))),"recordTypeHex",hex(str(row.get("record_type"))),"sourceKeyHex",hex(str(row.get("source_key"))),"sourceBookId",row.get("book_id"),"sourceBookDeleted",deleted(row.get("source_deleted")),"copyMatches",copyMatches,"rootKind",root,"present",present,"valueKind",cellKind,"valueSha256",valueHash));}
    static Boolean deleted(Object n){return n==null?null:num(n)!=0;}
    String hex(String s){return HexFormat.of().withUpperCase().formatHex(bytes(s));}
    JsonNode reviews(Query q){String scope=q.choice("scope","MEMBER_MARKER",List.of("MEMBER_MARKER","ALL")),deleted=q.choice("bookDeleted","EXCLUDE",List.of("EXCLUDE","ONLY","ALL")),keyword=q.keyword();List<String> reasons=q.many("reason",REASONS),markers=q.many("markerState",MARKERS);List<Object> args=new ArrayList<>();StringBuilder where=new StringBuilder(" WHERE 1=1");if(scope.equals("MEMBER_MARKER"))where.append(" AND has_marker=1");if(deleted.equals("EXCLUDE"))where.append(" AND deleted=0");if(deleted.equals("ONLY"))where.append(" AND deleted<>0");if(q.values.containsKey("associationState")){where.append(" AND association_state=?");args.add(q.choice("associationState",null,List.of("NO_SOURCE","VALID","ASSOCIATION_INVALID")));}if(q.values.containsKey("relationshipState")){where.append(" AND relationship_state=?");args.add(q.choice("relationshipState",null,List.of("NONE","ACTIVE","HISTORICAL")));}if(!markers.isEmpty()){where.append(" AND marker_state IN (").append(placeholders(markers.size())).append(")");args.addAll(markers);}if(!reasons.isEmpty()){List<String> cond=new ArrayList<>();for(String r:reasons)cond.add(switch(r){case "MEMBER_MARKER_NO_PARENT"->"has_marker=1";case "SOURCE_CONFLICT"->"variants>1";case "ASSOCIATION_INVALID"->"invalid_association>0";case "UNMAPPED_MARKER"->"has_unmapped=1";case "NO_SOURCE"->"source_count=0";case "INCOMPLETE_SOURCE_VALUE"->"has_incomplete=1";default->"source_count>200";});where.append(" AND (").append(String.join(" OR ",cond)).append(")");}if(!keyword.isEmpty()){where.append(" AND (title LIKE ? ESCAPE '!' OR display_title_override LIKE ? ESCAPE '!' OR isbn LIKE ? ESCAPE '!')");args.add(like(keyword));args.add(like(keyword));args.add(like(keyword));}String cte=cte();long total=jdbc.queryForObject(cte+"SELECT COUNT(*) FROM cases"+where,Long.class,args.toArray());args.add(q.size);args.add(q.offset);var rows=jdbc.queryForList(cte+"SELECT * FROM cases"+where+" ORDER BY CASE WHEN case_book IS NULL THEN 1 ELSE 0 END,case_book,orphan_id LIMIT ? OFFSET ?",args.toArray());Map<String,CaseData> data=load(rows.stream().map(CatalogSetSourceQuery::rowKey).toList());ArrayNode records=JSON.createArrayNode();for(var r:rows){String k=rowKey(r);records.add(obj("caseKey",k,"caseKind",bookCase(k)?"BOOK_SOURCE":"ORPHAN_SOURCE","book",bookCase(k)?CatalogSetService.bookIdentity(r):null,"source",data.get(k).summary(),"relationshipState",r.get("relationship_state"),"activeSetCount",r.get("active_count"),"historicalMembershipCount",r.get("history_count"),"catalogMembershipState",num(r.get("history_count"))>0?"HAS_CONFIRMED_RELATIONS":"NONE","sourceResolution","UNRESOLVED","physicalAssembly","UNVERIFIED"));}return page(records,total,q);}
    JsonNode details(String key,Query q){long id=caseId(key);String predicate=bookCase(key)?"case_book=?":"case_book IS NULL AND orphan_id=?";var subjects=jdbc.queryForList(cte()+"SELECT source_count FROM cases WHERE "+predicate,id);if(subjects.isEmpty())throw failure(404,"CASE_NOT_FOUND");long total=num(subjects.get(0).get("source_count"));String relation=bookCase(key)?"(r.book_id=? OR EXISTS(SELECT 1 FROM book_copy c WHERE c.book_id=? AND c.barcode_key="+bin("r.source_key")+"))":"r.id=?";List<Object> args=new ArrayList<>();args.add(id);if(bookCase(key))args.add(id);args.add(q.size);args.add(q.offset);List<Long> pageIds=jdbc.queryForList("SELECT r.id FROM ("+rawSql()+") r WHERE "+relation+" ORDER BY r.id LIMIT ? OFFSET ?",Long.class,args.toArray());CaseData data=load(List.of(key)).get(key);Map<Long,JsonNode> indexed=new HashMap<>();data.records.forEach(r->indexed.put(r.path("recordId").asLong(),r));ArrayNode records=JSON.createArrayNode();pageIds.forEach(recordId->records.add(indexed.get(recordId)));ObjectNode result=page(records,total,q);result.put("caseKey",key);result.put("evidenceDigest",data.digest());return result;}
}
